<script setup>
import {computed,ref} from 'vue';
import {progress,filterRequirements} from '../model.js';
const props=defineProps({requirements:{type:Array,default:()=>[]}});
const emit=defineEmits(['select']);
const view=ref('remaining');
const completedCount=computed(()=>props.requirements.filter(item=>item.status==='complete').length);
const remainingCount=computed(()=>props.requirements.length-completedCount.value);
const rows=computed(()=>filterRequirements(props.requirements,view.value)
 .map(item=>({item,chart:progress(item)}))
 .sort((a,b)=>(b.chart?.remaining??-1)-(a.chart?.remaining??-1)));
function credits(value){return Number.isFinite(value)?new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(value):'—';}
function label(row){const {item,chart}=row;return chart?`${item.title}: ${credits(item.completed)} of ${credits(item.required)} credits completed, ${credits(item.inProgress)} in progress, ${credits(chart.remaining)} still to earn, including current courses; ${credits(chart.additional)} additional credits needed after current courses.${item.status==='review'?' Needs review.':''}`:`${item.title}: credit totals need confirmation.`;}
</script>
<template>
 <section class="requirement-chart" aria-labelledby="requirement-chart-title">
  <div class="chart-header"><div><h2 id="requirement-chart-title">{{view==='complete'?'Completed requirements':'What’s left, by requirement'}}</h2><p>{{view==='complete'?'Requirements marked complete in your report.':'Largest credit gaps first.'}} Select a row to see its details.</p></div><div class="chart-filters" role="group" aria-label="Requirement chart filter"><button class="chart-toggle" type="button" :aria-pressed="view==='remaining'" @click="view='remaining'">To complete ({{remainingCount}})</button><button class="chart-toggle" type="button" :aria-pressed="view==='complete'" @click="view='complete'">Completed ({{completedCount}})</button></div></div>
  <div class="chart-key" aria-label="Chart legend"><span><i class="earned"></i>Completed</span><span><i class="current"></i>In progress</span><span><i class="remaining"></i>After current courses</span></div>
  <div v-if="rows.length" class="chart-rows">
   <button v-for="row in rows" :key="row.item.id" type="button" class="chart-row" :aria-label="label(row)+' Open requirement details.'" @click="emit('select',row.item)">
    <span class="row-heading"><span class="row-title">{{row.item.title}}<small v-if="row.item.status==='review'" class="review-label">Needs review</small></span><strong v-if="row.chart?.remaining>0">{{credits(row.chart.remaining)}} <small>credits still to earn</small></strong><strong v-else-if="row.chart && row.item.inProgress>0" class="pending">Pending current courses</strong><strong v-else-if="row.chart && row.item.status==='complete'" class="pending">Complete</strong><strong v-else class="pending">Needs confirmation</strong></span>
    <span v-if="row.chart" class="requirement-track" aria-hidden="true"><span class="earned" :style="{width:row.chart.completeWidth+'%'}"></span><span class="current" :style="{width:row.chart.progressWidth+'%'}"></span></span>
    <span v-else class="requirement-track unknown" aria-hidden="true"></span>
    <span class="row-caption"><span>{{credits(row.item.completed)}} / {{credits(row.item.required)}} credits completed<span v-if="Number.isFinite(row.item.inProgress) && row.item.inProgress>0"> · {{credits(row.item.inProgress)}} in progress</span><span v-if="row.chart"> · {{credits(row.chart.additional)}} needed after current courses</span></span><span>{{row.chart?'View details →':'Credit totals need confirmation →'}}</span></span>
   </button>
  </div>
  <p class="chart-count" role="status" aria-live="polite">Showing {{rows.length}} {{view==='complete'?'completed':'unfinished or unverified'}} requirements</p>
  <p v-if="!rows.length" class="chart-empty">{{!requirements.length?'No requirements were identified in this report.':view==='complete'?'No requirements are marked complete in this report yet. In-progress and needs-review items are under “To complete”.':'All listed requirements are marked complete. Select “Completed” to view them.'}}</p>
  <p class="chart-note">Each bar shows progress toward its own requirement. Still to earn = required minus completed. In-progress credits are not earned yet. The gray segment shows additional credits needed after current courses are passed. Requirements can overlap; do not add their credits together. Credit progress does not verify course eligibility.</p>
 </section>
</template>
<style scoped>
.requirement-chart{--earned:#1e407c;--current:#96bee6;--remaining:#e3eaf3;margin:28px 0;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:26px}.chart-header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.chart-header h2{font-size:22px;font-weight:550;letter-spacing:-.4px;margin:0}.chart-header p{font-size:15px;color:var(--muted);line-height:1.6;margin:7px 0 0}.chart-filters{display:flex;gap:6px;flex-wrap:wrap}.chart-toggle[aria-pressed="true"]{background:var(--psu-blue);color:var(--surface);border-color:var(--psu-blue)}.chart-count{font-size:13px;color:var(--muted);margin:12px 0 0}.chart-toggle{border:1px solid var(--line);border-radius:8px;padding:8px 12px;font-size:14px;white-space:nowrap;background:var(--surface-subtle)}.chart-key{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0 8px;font-size:14px;color:var(--muted)}.chart-key>span{display:flex;align-items:center;gap:7px}.chart-key i{width:9px;height:9px;border-radius:3px}.earned{background:var(--earned)}.current{background:var(--current)}.remaining{background:var(--remaining)}.chart-row{display:block;text-align:left;width:100%;padding:18px 10px;border-radius:8px;color:var(--ink)}.chart-row+.chart-row{border-top:1px solid var(--line)}.chart-row:hover{background:var(--surface-subtle);color:var(--ink)}.row-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:11px}.row-title{font-size:16px;line-height:1.6;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.review-label{font-size:12px;border:1px solid var(--line);color:var(--muted);padding:1px 6px;border-radius:4px}.row-heading>strong{font-size:22px;white-space:nowrap;font-variant-numeric:tabular-nums}.row-heading strong small{font-size:13px;color:var(--muted);font-weight:400}.row-heading>strong.pending{font-size:13px;color:var(--muted);font-weight:500}.requirement-track{display:flex;overflow:hidden;height:10px;border-radius:5px;width:100%;background:var(--remaining)}.requirement-track>span{height:100%}.requirement-track.unknown{background:repeating-linear-gradient(135deg,var(--surface-subtle),var(--surface-subtle) 6px,var(--line) 6px,var(--line) 8px)}.row-caption{display:flex;justify-content:space-between;gap:12px;margin-top:8px;font-size:13px;line-height:1.6;color:var(--muted)}.chart-note,.chart-empty{font-size:13px;line-height:1.8;color:var(--muted);margin:18px 0 0}.chart-empty{font-size:15px;padding:12px 0}:global([data-theme="dark"]) .requirement-chart{--earned:#729ed6;--current:#bfd5ee;--remaining:#383e48}@media(max-width:600px){.requirement-chart{padding:20px 14px}.chart-header{flex-direction:column;gap:10px}.row-heading{align-items:flex-start;gap:10px}.row-title{font-size:15px;gap:4px}.row-heading>strong{font-size:20px}.row-heading strong small{display:block}.row-caption{flex-direction:column;gap:2px}.chart-key{gap:14px}.chart-row{padding:16px 5px}.row-heading>strong.pending{max-width:100px;white-space:normal;text-align:right}}
</style>
